-- C10 / P10.6 — inbound communications are untrusted; triage/reply drafts never authorize sends.
create table if not exists public.command_center_social_inbound_message_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 message_event_id text not null check(btrim(message_event_id)<>''), message_id text not null check(btrim(message_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''), thread_id text not null check(btrim(thread_id)<>''), platform text not null check(btrim(platform)<>''), external_author_ref text not null check(btrim(external_author_ref)<>''),
 body text not null check(btrim(body)<>''), content_hash text not null check(btrim(content_hash)<>''), received_at timestamptz not null, observed_at timestamptz not null, source_refs text[] not null check(cardinality(source_refs)>0), trust text not null default 'untrusted_external' check(trust='untrusted_external'), instruction_authority text not null default 'none' check(instruction_authority='none'),
 primary key(owner_id,message_event_id), unique(owner_id,message_id), check(received_at<=observed_at)
);
create table if not exists public.command_center_social_inbox_triage_history (
 owner_id uuid not null, triage_event_id text not null check(btrim(triage_event_id)<>''), message_id text not null, account_id text not null check(btrim(account_id)<>''), category text not null check(category in ('question','support','lead','spam','unknown')), priority text not null check(priority in ('low','normal','high')), suspicious_instruction_like_content boolean not null, requires_owner_review boolean not null,
 trust text not null default 'untrusted_external' check(trust='untrusted_external'), instruction_authority text not null default 'none' check(instruction_authority='none'), send_authorized boolean not null default false check(send_authorized=false), observed_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 primary key(owner_id,triage_event_id), foreign key(owner_id,message_id) references public.command_center_social_inbound_message_history(owner_id,message_id) on delete restrict
);
create table if not exists public.command_center_social_reply_draft_history (
 owner_id uuid not null, reply_event_id text not null check(btrim(reply_event_id)<>''), reply_draft_id text not null check(btrim(reply_draft_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''), message_id text not null, thread_id text not null check(btrim(thread_id)<>''), reply_version integer not null check(reply_version>0), body text not null check(btrim(body)<>''), content_hash text not null check(btrim(content_hash)<>''), provenance_refs text[] not null check(cardinality(provenance_refs)>0), created_at timestamptz not null,
 send_authorized boolean not null default false check(send_authorized=false), primary key(owner_id,reply_event_id), unique(owner_id,reply_draft_id,reply_version), foreign key(owner_id,message_id) references public.command_center_social_inbound_message_history(owner_id,message_id) on delete restrict
);
create table if not exists public.command_center_social_communication_send_intents (
 owner_id uuid not null, send_intent_id text not null check(btrim(send_intent_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''), thread_id text not null check(btrim(thread_id)<>''), reply_draft_id text not null, reply_draft_version integer not null check(reply_draft_version>0), reply_content_hash text not null check(btrim(reply_content_hash)<>''), authorization_ref text not null check(btrim(authorization_ref)<>''), authorization_account_id text not null check(btrim(authorization_account_id)<>''), authorization_observed_at timestamptz not null, authorization_expires_at timestamptz not null, idempotency_key text not null check(btrim(idempotency_key)<>''), external_text_instruction_authority text not null default 'none' check(external_text_instruction_authority='none'),
 primary key(owner_id,send_intent_id), unique(owner_id,idempotency_key), foreign key(owner_id,reply_draft_id,reply_draft_version) references public.command_center_social_reply_draft_history(owner_id,reply_draft_id,reply_version) on delete restrict, check(authorization_account_id=account_id), check(authorization_observed_at<authorization_expires_at)
);
create or replace function public.command_center_reject_social_inbox_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social inbox evidence is immutable'; end $$;
drop trigger if exists command_center_social_inbound_immutable on public.command_center_social_inbound_message_history; create trigger command_center_social_inbound_immutable before update or delete on public.command_center_social_inbound_message_history for each row execute function public.command_center_reject_social_inbox_evidence_mutation();
drop trigger if exists command_center_social_triage_immutable on public.command_center_social_inbox_triage_history; create trigger command_center_social_triage_immutable before update or delete on public.command_center_social_inbox_triage_history for each row execute function public.command_center_reject_social_inbox_evidence_mutation();
drop trigger if exists command_center_social_reply_immutable on public.command_center_social_reply_draft_history; create trigger command_center_social_reply_immutable before update or delete on public.command_center_social_reply_draft_history for each row execute function public.command_center_reject_social_inbox_evidence_mutation();
drop trigger if exists command_center_social_send_intent_immutable on public.command_center_social_communication_send_intents; create trigger command_center_social_send_intent_immutable before update or delete on public.command_center_social_communication_send_intents for each row execute function public.command_center_reject_social_inbox_evidence_mutation();
alter table public.command_center_social_inbound_message_history enable row level security; alter table public.command_center_social_inbox_triage_history enable row level security; alter table public.command_center_social_reply_draft_history enable row level security; alter table public.command_center_social_communication_send_intents enable row level security;
revoke all on table public.command_center_social_inbound_message_history,public.command_center_social_inbox_triage_history,public.command_center_social_reply_draft_history,public.command_center_social_communication_send_intents from public,anon,authenticated;
grant select,insert on table public.command_center_social_inbound_message_history,public.command_center_social_inbox_triage_history,public.command_center_social_reply_draft_history,public.command_center_social_communication_send_intents to authenticated;
create policy p10_6_social_inbound_owner on public.command_center_social_inbound_message_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and trust='untrusted_external' and instruction_authority='none');
create policy p10_6_social_triage_owner on public.command_center_social_inbox_triage_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and send_authorized=false and instruction_authority='none');
create policy p10_6_social_reply_owner on public.command_center_social_reply_draft_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and send_authorized=false);
create policy p10_6_social_send_intent_owner on public.command_center_social_communication_send_intents for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and external_text_instruction_authority='none');
